PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber (AVG(?loss) AS ?averageLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:against ?coverage .

    ?coverage in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentAmount .
    }
    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveAmount .
    }
    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentAmount .
    }
    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveAmount .
    }

    BIND(
      COALESCE(xsd:decimal(?lossPaymentAmount), 0) +
      COALESCE(xsd:decimal(?lossReserveAmount), 0) +
      COALESCE(xsd:decimal(?expensePaymentAmount), 0) +
      COALESCE(xsd:decimal(?expenseReserveAmount), 0)
      AS ?loss
    )
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?premiumAmount
WHERE {
  SERVICE <mapped> {
    ?policyCoverageDetail a in:PolicyCoverageDetail ;
                          in:hasPolicy ?policy ;
                          in:hasPremiumAmount ?premium .
    ?policy in:policyNumber ?policyNumber .
    ?premium in:premiumAmount ?premiumAmount .
  }
}
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?coverageEffectiveDate ?coverageExpirationDate ?premiumAmount
WHERE {
  SERVICE <mapped> {
    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium ;
              in:policyCoverageEffectiveDate ?coverageEffectiveDate ;
              in:policyCoverageExpirationDate ?coverageExpirationDate .

    ?policy in:policyNumber ?policyNumber .
    ?premium in:premiumAmount ?premiumAmount .
  }
}
ORDER BY ?policyNumber ?coverageEffectiveDate ?coverageExpirationDate

PREFIX in: <http://data.world/schema/insurance/>

SELECT DISTINCT ?policyHolder ?claim ?catastrophe
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:hasPolicyHolder ?policyHolder .

    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:against ?pcd ;
           in:hasCatastrophe ?catastrophe .
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy .
  }
}
